import json, csv
def solve():
    with open('/app/data/instance.txt') as f:
        lines = f.readlines()
    n_jobs, n_machines = map(int, lines[0].split())
    jobs_data, idx = [], 1
    for j in range(n_jobs):
        n_ops = int(lines[idx]); idx += 1
        ops = []
        for o in range(n_ops):
            pts = list(map(int, lines[idx].split())); idx += 1
            ops.append({pts[i+1]: pts[i+2] for i in range(0, len(pts), 2)})
        jobs_data.append(ops)
    with open('/app/data/downtime.csv') as f:
        downtimes = list(csv.DictReader(f))
        for d in downtimes: 
            d['m'], d['s'], d['e'] = int(d['machine']), int(d['start']), int(d['end'])
    with open('/app/data/policy.json') as f: policy = json.load(f)
    with open('/app/data/baseline_solution.json') as f: baseline = json.load(f)
    bl_ops = {(it['job'], it['op']): it for it in baseline['schedule']}
    fr_t = policy['freeze']['freeze_until']
    locked = []
    if policy['freeze']['enabled']:
        for (j, o), it in bl_ops.items():
            if it['start'] <= fr_t:
                if not any(d['m'] == it['machine'] and not (it['end'] <= d['s'] or it['start'] >= d['e']) for d in downtimes):
                    locked.append((j, o))
    sched = {}
    for (j, o) in locked:
        it = bl_ops[(j, o)]
        sched[(j, o)] = {'job': j, 'op': o, 'machine': it['machine'], 'start': it['start'], 'end': it['end'], 'dur': it['dur']}
    to_sched = [(j, o) for j in range(n_jobs) for o in range(len(jobs_data[j])) if (j, o) not in locked]
    while to_sched:
        avail = sorted([op for op in to_sched if op[1] == 0 or (op[0], op[1]-1) in sched], key=lambda x: bl_ops[x]['start'])
        curr_j, curr_o = avail[0]; to_sched.remove((curr_j, curr_o))
        best_m, best_s, bl_m = None, 1e9, bl_ops[(curr_j, curr_o)]['machine']
        e_s = sched[(curr_j, curr_o-1)]['end'] if curr_o > 0 else 0
        for m, dur in jobs_data[curr_j][curr_o].items():
            t = e_s
            while True:
                if all(not (t+dur > it['start'] and t < it['end']) for it in sched.values() if it['machine'] == m) and all(not (t+dur > d['s'] and t < d['e']) for d in downtimes if d['m'] == m):
                    break
                t += 1
            if t < best_s or (t == best_s and m == bl_m):
                best_s, best_m = t, m
        sched[(curr_j, curr_o)] = {'job': curr_j, 'op': curr_o, 'machine': best_m, 'start': best_s, 'end': best_s + jobs_data[curr_j][curr_o][best_m], 'dur': jobs_data[curr_j][curr_o][best_m]}
    final = sorted(sched.values(), key=lambda x: (x['start'], x['machine']))
    res = {"status": "OPTIMIZED", "makespan": max(it['end'] for it in final), "schedule": final}
    with open('/app/output/solution.json', 'w') as f: json.dump(res, f, indent=2)
    with open('/app/output/schedule.csv', 'w', newline='') as f:
        w = csv.DictWriter(f, fieldnames=['job', 'op', 'machine', 'start', 'end', 'dur'])
        w.writeheader(); w.writerows(final)
    print(f"Makespan: {res['makespan']}")
solve()
